-- =================================================================
-- RLS Policies
-- =================================================================

-- Policy for training_plans: Users can manage their own plans.
CREATE POLICY "Allow individual access to own training plans"
ON public.training_plans
FOR ALL
USING (auth.uid() = user_id);

-- Policy for training_sessions: Users can manage their own sessions.
CREATE POLICY "Allow individual access to own training sessions"
ON public.training_sessions
FOR ALL
USING (auth.uid() = user_id);

-- Policy for training_history: Users can manage their own history.
CREATE POLICY "Allow individual access to own training history"
ON public.training_history
FOR ALL
USING (auth.uid() = user_id);

-- Policy for body_measurements: Users can manage their own measurements.
CREATE POLICY "Allow individual access to own body measurements"
ON public.body_measurements
FOR ALL
USING (auth.uid() = user_id);

-- Policy for custom_actions: Users can manage their own custom actions.
CREATE POLICY "Allow individual access to own custom actions"
ON public.custom_actions
FOR ALL
USING (auth.uid() = user_id);

-- For tables that don't have a direct user_id, access should be managed through joins in your application logic or using security barrier views.
-- For example, to access plan_actions, you must first have access to the training_plan.

-- Grant usage on schemas
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT USAGE ON SCHEMA system_content TO postgres, anon, authenticated, service_role;

-- Grant permissions for public schema
GRANT ALL ON ALL TABLES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;

-- Grant permissions for system_content schema (read-only for users)
GRANT SELECT ON ALL TABLES IN SCHEMA system_content TO anon, authenticated;